PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE organizations(id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE users(id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, time_zone TEXT NOT NULL DEFAULT 'UTC');
CREATE TABLE memberships(org_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','admin','manager','contributor','guest','viewer')), state TEXT NOT NULL CHECK(state IN ('active','suspended')), PRIMARY KEY(org_id,user_id));
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL);
CREATE TABLE invitations(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), email TEXT NOT NULL, role TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, accepted_at TEXT, revoked_at TEXT, created_by TEXT NOT NULL REFERENCES users(id));
CREATE TABLE projects(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), project_key TEXT NOT NULL, name TEXT NOT NULL, archived_at TEXT, next_task_number INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(org_id,project_key));
CREATE TABLE project_members(project_id TEXT NOT NULL REFERENCES projects(id), user_id TEXT NOT NULL REFERENCES users(id), permission TEXT NOT NULL CHECK(permission IN ('manager','contributor','guest','viewer')), PRIMARY KEY(project_id,user_id));
CREATE TABLE boards(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(project_id,name));
CREATE TABLE columns(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), board_id TEXT NOT NULL REFERENCES boards(id), name TEXT NOT NULL, rank REAL NOT NULL, wip_limit INTEGER CHECK(wip_limit IS NULL OR wip_limit > 0), UNIQUE(board_id,name));
CREATE TABLE tasks(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), project_id TEXT NOT NULL REFERENCES projects(id), column_id TEXT NOT NULL REFERENCES columns(id), task_number INTEGER NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', priority TEXT NOT NULL CHECK(priority IN ('low','medium','high','urgent')), rank REAL NOT NULL, version INTEGER NOT NULL DEFAULT 1, creator_id TEXT NOT NULL REFERENCES users(id), due_at TEXT, archived_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,task_number));
CREATE INDEX tasks_tenant_search ON tasks(org_id,project_id,column_id,rank,id);
CREATE INDEX tasks_title_search ON tasks(org_id,title);
CREATE TABLE labels(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL, color TEXT NOT NULL, UNIQUE(project_id,name));
CREATE TABLE task_labels(task_id TEXT NOT NULL REFERENCES tasks(id), label_id TEXT NOT NULL REFERENCES labels(id), PRIMARY KEY(task_id,label_id));
CREATE TABLE task_assignments(task_id TEXT NOT NULL REFERENCES tasks(id), user_id TEXT NOT NULL REFERENCES users(id), assigned_by TEXT NOT NULL REFERENCES users(id), assigned_at TEXT NOT NULL, PRIMARY KEY(task_id,user_id));
CREATE TABLE comments(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), task_id TEXT NOT NULL REFERENCES tasks(id), author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at TEXT NOT NULL, edited_at TEXT, deleted_at TEXT);
CREATE TABLE attachments(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), task_id TEXT NOT NULL REFERENCES tasks(id), uploader_id TEXT NOT NULL REFERENCES users(id), file_name TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL CHECK(size > 0 AND size <= 5000000), checksum TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, scan_state TEXT NOT NULL CHECK(scan_state IN ('pending','clean','quarantined','failed')), created_at TEXT NOT NULL);
CREATE TABLE saved_views(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), project_id TEXT NOT NULL REFERENCES projects(id), owner_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN ('personal','project')), filters_json TEXT NOT NULL, sort TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE activities(id INTEGER PRIMARY KEY AUTOINCREMENT, org_id TEXT NOT NULL REFERENCES organizations(id), project_id TEXT, task_id TEXT, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}', occurred_at TEXT NOT NULL);
CREATE INDEX activities_tenant_time ON activities(org_id,occurred_at DESC,id DESC);
CREATE TABLE notifications(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), recipient_id TEXT NOT NULL REFERENCES users(id), activity_id INTEGER REFERENCES activities(id), dedupe_key TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('unread','read')), created_at TEXT NOT NULL, UNIQUE(recipient_id,dedupe_key));
CREATE TABLE webhooks(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), endpoint TEXT NOT NULL, secret TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE webhook_deliveries(id TEXT PRIMARY KEY, webhook_id TEXT NOT NULL REFERENCES webhooks(id), activity_id INTEGER NOT NULL REFERENCES activities(id), attempt INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL CHECK(state IN ('pending','delivered','dead')), next_attempt_at TEXT NOT NULL, last_error TEXT, UNIQUE(webhook_id,activity_id));
CREATE TABLE jobs(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), kind TEXT NOT NULL, payload_json TEXT NOT NULL, dedupe_key TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','running','complete','dead')), attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, last_error TEXT, created_at TEXT NOT NULL, UNIQUE(org_id,kind,dedupe_key));
CREATE TABLE idempotency_keys(org_id TEXT NOT NULL REFERENCES organizations(id), scope TEXT NOT NULL, key TEXT NOT NULL, response_json TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(org_id,scope,key));
